const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function alikenessOf(component: Item): string {
  return component.type;
}

function groupAlike(components: Item[]): Map<string, number> {
  const alikeCounts = new Map<string, number>();
  for (const component of components) {
    const alikeness = alikenessOf(component);
    alikeCounts.set(alikeness, (alikeCounts.get(alikeness) ?? 0) + 1);
  }
  return alikeCounts;
}

function formsBlock(alikeCount: number): boolean {
  return alikeCount === BLOCK_SIZE;
}

function alikeComponentsBasePremiumOf(alikeCount: number): number {
  return formsBlock(alikeCount) ? BLOCK_BASE_PREMIUM : alikeCount * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremiumOf(components: Item[]): number {
  let total = 0;
  for (const count of groupAlike(components).values()) {
    total += alikeComponentsBasePremiumOf(count);
  }
  return total;
}

function mainItemsBasePremiumOf(mainItems: Item[]): number {
  return mainItems.reduce((total, item) => total + MAIN_ITEM_BASE_PREMIUMS[item.type], 0);
}

function policyBasePremiumOf(items: Item[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);
  return mainItemsBasePremiumOf(mainItems) + componentsBasePremiumOf(components);
}

export function quote(customer: Customer, items: Item[]): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
}

