/** What the MHPCO insures: the price list prices it, the policy carries it. */
export interface Item {
  type: string;
  cursed?: boolean;
  enchantment?: number;
}

/**
 * One row of the MHPCO price list. The office publishes both columns for an item
 * type in one editorial act, so they are carried together rather than in separate
 * tables that would have to be kept aligned by hand.
 */
interface PriceListEntry {
  insuranceValue?: number;
  basePremium: number;
}

/**
 * Main items are listed by type. Insurance values the office has not yet published
 * are absent; the premium column is complete.
 */
const MAIN_ITEMS: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { basePremium: 80 },
  potion: { basePremium: 40 },
};

/** Components are not listed by type: the office carries the whole class at one rate. */
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_ENTRY: PriceListEntry = { insuranceValue: 250, basePremium: 25 };

export function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function entryFor(item: Item): PriceListEntry | undefined {
  return isComponent(item) ? COMPONENT_ENTRY : MAIN_ITEMS[item.type];
}

/**
 * The price list is the single authority on what the MHPCO insures: an item type it
 * does not carry is uninsurable, so the lookup that prices an item is also the one
 * that rejects it.
 */
export function basePremiumOf(item: Item): number {
  const entry = entryFor(item);
  if (entry === undefined) {
    throw new Error(`The MHPCO price list does not cover items of type "${item.type}".`);
  }
  return entry.basePremium;
}

/**
 * What the office carries for an item. The MHPCO has not yet published an insurance
 * value for every type it prices, so this column can be absent -- unlike the premium
 * column, this lookup does not yet reject an unlisted type. Both gaps are still
 * driven by inactive tests.
 */
export function insuranceValueOf(item: Item): number | undefined {
  return entryFor(item)?.insuranceValue;
}
import { type Item, insuranceValueOf } from "./price-list.js";

export type { Item };

/**
 * The cap a policy is measured against is built on what the MHPCO carries for the
 * items, not on the premium it charges for them: a block discount cuts the premium
 * and leaves the insurance sum untouched.
 */
export function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item)!, 0);
}

