import { type Item } from "./price-list.js";

/** What one damaged item lost in an incident, as the claim report states it. */
export interface Damage {
  itemType: string;
  amount: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

/**
 * What the office owes for one damaged item: the damage it carries, less the
 * deductible charged per damage event -- an incident that harms two items is
 * reduced twice, so the payout is assembled per damaged item rather than per
 * incident.
 *
 * No special clause is in force yet, so the office carries the damage in full.
 * The MHPCO's two clauses -- 50 % for enchantment >= 8, full reimbursement for
 * dragon material -- will decide the carried share from the damaged item's own
 * attributes; both are still driven by inactive tests.
 */
function reimbursementFor(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

/**
 * A claim is settled against the policy's items: the special clauses read the
 * damaged item's enchantment and material, so `items` is the policy side of that
 * lookup. Nothing consults it while full reimbursement is the only rule in force,
 * so it stays deliberately unused rather than being wired up ahead of the clause
 * that needs it.
 */
export function payoutFor(_items: Item[], damages: Damage[]): number {
  return damages.reduce((payout, damage) => payout + reimbursementFor(damage), 0);
}

